function expandHome(d){if(!d||d.sections.some(s=>s.id==='hd-start'))return d;if(d.sections.length>6||d.sections.flatMap(s=>s.blocks).length>16)return d;const copy=clone(d);copy.sections.splice(1,0,{id:'hd-start',name:'Everyday help',tone:'plain',blocks:[depthBlock('services','hd-home-services','How can we help?',8,{count:4}),depthBlock('directory','hd-home-people','Find your people',4)]});copy.sections.splice(3,0,{id:'hd-explore',name:'Explore your company',tone:'plain',blocks:[depthBlock('departments','hd-home-teams','Explore our teams',8,{count:4}),depthBlock('knowledge','hd-home-guides','Useful this week',4,{count:3})]});return copy;}
