function guideInfo(id){const seed=knowledgeSeeds.find(k=>k.id===id)||{id,team:'people',owner:'ella',kind:'Guide',topics:[]},record=pageRecord('guide-'+id);if(!record?.published||record.published.kind!=='knowledge')return null;const d=record.published,kind=d.docType||seed.kind;return {...seed,title:d.title,summary:d.tagline,team:d.department||seed.team,owner:d.owner||seed.owner,kind,checklist:kind==='Checklist'?(d.checklistText??seed.checklist?.join('\n')??'').split('\n').map(s=>s.trim()).filter(Boolean).slice(0,12):null,record,doc:d};}
