function depthSearch(id,label,value,placeholder){return `<form class="hd-search" data-depth-search="${id}">${I('search')}<input aria-label="${esc(label)}" value="${esc(value)}" placeholder="${esc(placeholder)}">${IB('Search '+label,'hd-search','arrow-right',id)}</form>`;}
function depthEmpty(title,text,action='',value=''){return `<div class="hd-empty"><h3>${title}</h3><p>${text}</p>${action?B('Clear filters',action,'rotate-ccw','',value):''}</div>`;}
function companyFooter(){return `<footer class="hd-company-footer"><div><h3>Our people. Our shared space.</h3><p>One company, connected across our sites.<br>Company Hub · Managed by People & Culture.</p></div><div><h3>Find your way</h3>${TB('Meet our teams','hd-route','teams','')}${TB('Find a colleague','hd-route','directory','')}${TB('Explore our knowledge','hd-route','resources','')}</div><div><h3>Here to help</h3>${TB('Get IT help','hd-service','it','')}${TB('Ask People & Culture','hd-service','hr','')}${TB('My sample requests','hd-my-requests','','')}</div></footer>`;}
function compactPerson(p,action='hd-person'){return `<button class="hd-org-node" data-action="${action}" data-value="${p.id}">${avatar(p.name)}<span><b>${esc(p.name)}</b><small>${esc(p.role)}</small></span></button>`;}
function spaceCards(compact=false,count=4){const teams=companyTeams.filter(t=>spaceRecord(t.id)?.published).slice(0,count);return `<div class="${compact?'hd-compact-grid':'hd-grid'}">${teams.map(t=>{const d=spaceRecord(t.id).published,lead=personBy(t.lead);return compact?`<button class="hd-shortcut" data-action="hd-space" data-value="${t.id}"><span class="hd-glyph">${I(t.icon)}</span><span><b>${esc(d.title)}</b><small>${t.topics[0]} · ${t.topics[1]}</small></span>${I('arrow-up-right')}</button>`:`<button class="hd-space-card" data-action="hd-space" data-value="${t.id}"><div class="hd-space-cover">${photo(heroFor(d).image,t.name)}<span class="hd-space-mark">${I(t.icon)}</span></div><div class="hd-space-copy"><h3>${esc(d.title)}</h3><p>${esc(d.summary||t.summary)}</p><div class="hd-space-meta"><span class="hc-row">${avatar(lead.name)}${esc(lead.name)}</span><span class="hc-row">Explore space ${I('arrow-up-right')}</span></div></div></button>`;}).join('')||depthEmpty('No department spaces are published','Published spaces will appear here.')}</div>`;}
function teamsPage(){return heading('Our company','Meet the teams behind your day','Explore their updates, find the right people and discover the resources they maintain.')+spaceCards()+`<div class="hd-ownerbar"><span class="hc-row">${I('building-2')}One organisation · Connected across our sites</span>${TB('See the organisation chart','hd-org','','network')}</div>`+companyFooter();}
function departmentPage(){const d=activeDoc(),t=teamBy(d.department),r=pageRecord(activePageId),lead=personBy(t.lead);if(preview)return depthBase.dedicatedPage();let content='';if(spaceTab==='overview')content=`<div class="hc-board">${d.sections.map(s=>sectionMarkup(s)).join('')}</div>`;if(spaceTab==='news'){const items=allStoryItems().filter(s=>pageRecord(s.id)?.published?.department===t.id);content=items.length?newsMarkup(items):depthEmpty('No updates yet','Published stories from this team will appear here.');}if(spaceTab==='knowledge')content=knowledgeRows(guideList().filter(k=>k.team===t.id));if(spaceTab==='people')content=peopleCards(colleagues.filter(p=>p.department===t.id));return `<div class="hd-ownerbar"><span class="hc-row">${avatar(lead.name)}<span>Space owner · ${TB(esc(lead.name),'hd-person',lead.id,'')}</span></span><div class="hc-row">${B(state.followedTeams.includes(t.id)?'Following':'Follow team','hd-follow-team',state.followedTeams.includes(t.id)?'check':'plus','',t.id)}${state.role==='editor'?B(r?.draft?'Continue draft':'Edit space','edit-content-page','pencil','',activePageId):''}</div></div><nav class="hd-section-tabs" aria-label="Department space">${[['overview','Overview'],['news','Updates'],['knowledge','Resources'],['people','Our team']].map(([key,label])=>`<button data-action="hd-space-tab" data-value="${key}" aria-pressed="${spaceTab===key}">${label}</button>`).join('')}${state.role==='editor'?`<span style="margin-left:auto">${B('New update','hd-new-update','plus','ghost',t.id)}</span>`:''}</nav>${content}<footer class="hc-pagefoot">${TB('All department spaces','hd-route','teams','arrow-left')}<span>${esc(d.title)} · Version ${r.revision} · Shared with all staff</span></footer>`;}
function peopleCards(items){return `<div class="hd-people-grid">${items.map(p=>`<button class="hd-person-card" data-action="hd-person" data-value="${p.id}"><div class="hc-row hc-between">${avatar(p.name)}${I('arrow-up-right')}</div><div><h3>${p.name}</h3><p>${p.role}<br>${teamName(p.department)}</p></div><div class="hd-person-base">${I('map-pin')}${p.site}</div></button>`).join('')||depthEmpty('No colleagues match those filters','Try another name, skill, team or site.','hd-people-clear')}</div>`;}
function organisationChart(){return `<div class="hd-org"><div class="hd-org-top">${compactPerson(personBy('alex'))}</div><div class="hd-org-branches">${companyTeams.map(t=>`<section class="hd-org-branch" aria-label="${t.name}">${compactPerson(personBy(t.lead))}${colleagues.filter(p=>p.manager===t.lead).map(p=>compactPerson(p)).join('')}</section>`).join('')}</div><p class="hm-note">${I('mouse-pointer-2')}Select a colleague to see their profile, reporting line and work contacts.</p></div>`;}
function peoplePage(){if(personId)return profilePage(personBy(personId));const q=peopleSearch.toLowerCase(),items=colleagues.filter(p=>(peopleDepartment==='all'||p.department===peopleDepartment)&&(peopleSite==='all'||p.site===peopleSite)&&(!q||(p.name+' '+p.role+' '+p.skills.join(' ')).toLowerCase().includes(q)));return heading('Our people','A familiar face. The right person.','Find colleagues across our company by name, team, site or area of expertise.')+`<div class="hd-toolbar">${peopleView==='cards'?`${depthSearch('people','People directory',peopleSearch,'Search name, role or expertise…')}<select data-depth-filter="people-department" aria-label="Filter people by team"><option value="all">All teams</option>${[...companyTeams.map(t=>[t.id,t.name]),['company','Company leadership']].map(([id,name])=>`<option value="${id}" ${peopleDepartment===id?'selected':''}>${name}</option>`).join('')}</select><select data-depth-filter="people-site" aria-label="Filter people by site"><option value="all">All sites</option>${['Support office','Harbour House','Kōwhai House'].map(s=>`<option ${peopleSite===s?'selected':''}>${s}</option>`).join('')}</select>`:'<span class="hc-small hc-muted" style="margin-right:auto">Company reporting lines · Fictional people</span>'}<div class="hd-view-switch" aria-label="Directory view">${[['cards','Directory','users-round'],['org','Organisation','network']].map(([key,label,icon])=>`<button data-action="hd-people-view" data-value="${key}" aria-pressed="${peopleView===key}">${I(icon)}${label}</button>`).join('')}</div></div>${peopleView==='org'?organisationChart():`<p class="hd-results-count">${items.length} ${items.length===1?'colleague':'colleagues'}${q||peopleDepartment!=='all'||peopleSite!=='all'?' · Filtered results':''}</p>${peopleCards(items)}`} ${companyFooter()}`;}
function profilePage(p){const manager=personBy(p.manager),reports=colleagues.filter(x=>x.manager===p.id),team=teamBy(p.department);return `<div class="hd-breadcrumb">${TB('People directory','hd-people-back','','arrow-left')}<span> / ${p.name}</span></div><div class="hd-profile-intro"><div class="hd-profile-top">${avatar(p.name)}<div><span class="hd-eyebrow">${teamName(p.department)}</span><h2>${p.name}</h2><p>${p.role} · ${p.site}</p></div>${B('Contact','hd-contact','message-circle','primary',p.id)}</div></div><div class="hd-profile"><div class="hc-stack"><section class="hd-surface hd-pad"><h3>About ${p.name.split(' ')[0]}</h3><p>${p.about}</p><h3 style="margin-top:22px">I can help with</h3><div class="hd-chips">${p.skills.map(s=>`<span class="hd-chip">${s}</span>`).join('')}</div></section><section class="hd-surface hd-pad"><h3>Where I fit</h3>${manager?`<small>Reports to</small><div style="margin:9px 0 16px">${compactPerson(manager)}</div>`:'<p>Leads the company leadership team.</p>'}${reports.length?`<small>Direct reports · ${reports.length}</small><div class="hd-profile-links" style="margin-top:9px">${reports.map(compactPerson).join('')}</div>`:''}${!reports.length?`<p>Part of ${teamName(p.department)}.</p>`:''}</section></div><aside class="hc-stack"><section class="hd-surface hd-pad"><h3>Work details</h3><div class="hd-contact-line">${I('mail')}<span><small>Work email · example</small>${personEmail(p)}</span></div><div class="hd-contact-line">${I('map-pin')}<span><small>Primary site</small>${p.site}</span></div><div class="hd-contact-line">${I('building-2')}<span><small>Team</small>${teamName(p.department)}</span></div></section>${team?`<section class="hd-surface hd-pad"><h3>Explore the team</h3><p>${team.summary}</p><div style="margin-top:14px">${B('Visit team space','hd-space','arrow-up-right','',team.id)}</div></section>`:''}</aside></div><footer class="hc-pagefoot"><span>Directory information comes from staff records.</span>${state.role==='editor'?TB('Preview staff record','hd-staff-record',p.id,'arrow-up-right'):'<span>Fictional profile</span>'}</footer>`;}
function serviceSubset(department='all'){return department==='all'?['it','leave','policy','hr'].map(id=>staffServices.find(s=>s.id===id)):staffServices.filter(s=>s.team===department);}
function serviceTiles(items,compact=false){return `<div class="${compact?'hd-compact-grid':'hd-service-grid'}">${items.map(s=>compact?`<button class="hd-shortcut" data-action="hd-service" data-value="${s.id}"><span class="hd-glyph">${I(s.icon)}</span><span><b>${s.title}</b><small>${s.mode==='request'?'Ask the team':s.mode==='knowledge'?'Browse knowledge':'Open application area'}</small></span>${I('arrow-up-right')}</button>`:`<button class="hd-service-card" data-action="hd-service" data-value="${s.id}"><span class="hd-glyph">${I(s.icon)}</span><h3>${s.title}</h3><p>${s.summary}</p><footer><span>${teamName(s.team)}</span>${I('arrow-up-right')}</footer></button>`).join('')||depthEmpty('No services match','Try another service or team.','hd-services-clear')}</div>`;}
function servicePage(){if(requestId)return requestPage(requestId);const q=serviceSearch.toLowerCase(),items=staffServices.filter(s=>(serviceDepartment==='all'||s.team===serviceDepartment)&&(!q||(s.title+' '+s.summary).toLowerCase().includes(q)));return `<section class="hd-service-feature"><div><span class="hd-eyebrow">Staff service centre</span><h2>How can we help?</h2><p>Find the right service, start a request or get straight to the information you need.</p>${depthSearch('services','Staff services',serviceSearch,'What do you need help with?')}</div><aside><h3>A helpful place to start</h3>${TB('Explore the staff handbook','hd-article','handbook','book-open')}${TB('Meet our support teams','hd-route','teams','users-round')}${TB('My sample requests','hd-my-requests','','inbox')}</aside></section><nav class="hd-section-tabs" aria-label="Staff services"><button data-action="hd-service-view" data-value="services" aria-pressed="${serviceView==='services'}">Services</button><button data-action="hd-service-view" data-value="requests" aria-pressed="${serviceView==='requests'}">My requests <span class="hc-tag">${allRequests().length}</span></button></nav>${serviceView==='requests'?requestList():`<div class="hm-albums">${[['all','All services'],...companyTeams.map(t=>[t.id,t.name])].map(([id,name])=>`<button data-action="hd-service-filter" data-value="${id}" aria-pressed="${serviceDepartment===id}">${name}</button>`).join('')}</div>${serviceTiles(items)}`}<p class="hm-note">${I('flask-conical')}Requests and application links are demonstrations. Nothing is sent to a live team.</p>${companyFooter()}`;}
function allRequests(){return [...state.serviceRequests,...requestSamples];}
function requestList(){return `<div class="hd-surface">${allRequests().map(r=>`<div class="hd-request-row"><div><b>${esc(r.title)}</b><p>${r.id} · ${staffServices.find(s=>s.id===r.service)?.title} · ${r.date}</p></div><span class="hc-tag ${r.status==='Completed'?'success':''}">${r.status}</span>${IB('Open request '+r.id,'hd-request','arrow-up-right',r.id)}</div>`).join('')}</div>`;}
function requestPage(id){const r=allRequests().find(r=>r.id===id);if(!r)return depthEmpty('Request unavailable','Return to your requests to choose an example.');const s=staffServices.find(s=>s.id===r.service),owner=personBy(r.owner);return `<div class="hd-breadcrumb">${TB('My sample requests','hd-my-requests','','arrow-left')}<span> / ${r.id}</span></div>${heading('Sample request',esc(r.title),s.title+' · '+r.site,`<span class="hc-tag ${r.status==='Completed'?'success':''}">${r.status}</span>`)}<div class="hd-profile"><div class="hc-stack"><section class="hd-surface hd-pad"><h3>Your request</h3><p>${esc(r.detail)}</p></section><section class="hd-surface hd-pad"><h3>Activity</h3><div class="hd-timeline">${(r.activity||[['Sample request created',r.date],['Ready for the team to review','No live notification sent']]).map(([label,date])=>`<div><b>${esc(label)}</b><p>${esc(date)}</p></div>`).join('')}</div></section></div><aside class="hc-stack"><section class="hd-surface hd-pad"><h3>Looking after this</h3>${owner?compactPerson(owner):`<p>${teamName(s.team)} queue</p>`}<p style="margin-top:13px">${r.status==='Completed'?'This sample request is complete.':'You would receive updates here when the team responds.'}</p></section><section class="hd-surface hd-pad"><h3>While you’re here</h3>${TB(guideInfo(s.guide)?.title||'Read a guide','hd-article',s.guide,'book-open')}</section></aside></div>`;}
function showService(id){const s=staffServices.find(x=>x.id===id);if(!s)return;selectedService=s.id;if(s.mode==='knowledge'){routeDepth('resources');return;}if(s.mode==='handoff'){openDialog(s.title,'Continue in the existing application',`<div class="hd-dialog-highlight">${I(s.icon)} <strong>${esc(s.destination)}</strong><p style="margin-top:8px">${s.summary}</p></div><p class="hc-small hc-muted">This mockup previews the hand-off. Your existing ${s.team==='learning'?'learning':'HR'} workflow would open here.</p><div style="margin-top:18px">${TB('Read the guide first','hd-article',s.guide,'book-open')}</div>`,B('Back','close')+B('Preview destination','hd-handoff','arrow-up-right','primary',s.id));return;}requestDraft={service:id,title:'',detail:'',site:'Support office'};showRequestForm();}
function showRequestForm(){const s=staffServices.find(s=>s.id===requestDraft.service);openDialog(s.title,'Create a sample request · '+teamName(s.team),`<div class="hd-dialog-highlight">${s.hint}</div><label class="hc-field">Summary<input id="hd-request-title" aria-label="Request summary" maxlength="90" placeholder="A short description of what you need" value="${esc(requestDraft.title)}"></label><label class="hc-field">Site<select id="hd-request-site" aria-label="Request site">${['Support office','Harbour House','Kōwhai House'].map(site=>`<option ${requestDraft.site===site?'selected':''}>${site}</option>`).join('')}</select></label><label class="hc-field">Details<textarea id="hd-request-detail" aria-label="Request details" rows="3" maxlength="350" placeholder="Use fictional details for this preview.">${esc(requestDraft.detail)}</textarea></label><p class="hm-error" id="hd-request-error" role="alert"></p><p class="hc-small hc-muted">This creates a sample in My requests. No message is sent.</p>`,B('Cancel','close')+B('Review request','hd-request-review','arrow-right','primary'));}
function reviewRequest(){requestDraft.title=root.querySelector('#hd-request-title').value.trim();requestDraft.detail=root.querySelector('#hd-request-detail').value.trim();requestDraft.site=root.querySelector('#hd-request-site').value;if(requestDraft.title.length<4||requestDraft.detail.length<8){root.querySelector('#hd-request-error').textContent='Add a clear summary and a little detail before continuing.';return;}const s=staffServices.find(s=>s.id===requestDraft.service);openDialog('Review your sample request',s.title,`<div class="hc-detailfacts"><span><small>Team</small>${teamName(s.team)}</span><span><small>Site</small>${esc(requestDraft.site)}</span></div><div class="hc-detailprose"><h3>${esc(requestDraft.title)}</h3><p>${esc(requestDraft.detail)}</p></div><p class="hm-note">${I('flask-conical')}This preview creates a sample record only.</p>`,B('Back to edit','hd-request-back','arrow-left')+B('Create sample request','hd-request-submit','check','primary'));}
function knowledgeRows(items){return `<div class="hd-surface">${items.map(k=>`<div class="hd-doc-row"><span class="hd-glyph">${I(k.kind==='Checklist'?'list-checks':k.kind==='Process'?'workflow':'book-open')}</span><button class="hd-doc-main" data-action="hd-article" data-value="${k.id}"><h3>${esc(k.title)}</h3><p>${esc(k.summary)}</p><small>${k.kind} · ${teamName(k.team)} · Updated ${k.doc.date}</small></button>${IB(state.bookmarks.includes('page:guide-'+k.id)?'Unsave '+k.title:'Save '+k.title,'hd-save-guide',state.bookmarks.includes('page:guide-'+k.id)?'bookmark-check':'bookmark',k.id)}</div>`).join('')||depthEmpty('No guides match those filters','Try another topic or a shorter search.','hd-knowledge-clear')}</div>`;}
function knowledgePage(){const q=knowledgeSearch.toLowerCase(),all=guideList(),items=all.filter(k=>(knowledgeTopic==='all'||k.team===knowledgeTopic)&&(knowledgeKind==='all'||k.kind===knowledgeKind)&&(!knowledgeSaved||state.bookmarks.includes('page:guide-'+k.id))&&(!q||(k.title+' '+k.summary+' '+k.topics.join(' ')).toLowerCase().includes(q)));return heading('Company knowledge','Find a useful answer','Practical guides, shared processes and checklists, with clear owners and review dates.')+`<div class="hd-toolbar">${depthSearch('knowledge','Knowledge library',knowledgeSearch,'Search guidance, processes and topics…')}<select data-depth-filter="knowledge-kind" aria-label="Filter knowledge by type">${[['all','All types'],['Guide','Guides'],['Process','Processes'],['Checklist','Checklists']].map(([id,name])=>`<option value="${id}" ${knowledgeKind===id?'selected':''}>${name}</option>`).join('')}</select><button class="hc-btn" data-action="hd-knowledge-saved" aria-pressed="${knowledgeSaved}">${I(knowledgeSaved?'bookmark-check':'bookmark')}Saved guides</button></div><div class="hd-knowledge-layout"><aside class="hd-taxonomy" aria-label="Knowledge topics"><h3>Browse by team</h3>${[['all','All knowledge','library'],...companyTeams.map(t=>[t.id,t.name,t.icon])].map(([id,name,icon])=>`<button data-action="hd-knowledge-topic" data-value="${id}" aria-pressed="${knowledgeTopic===id}">${I(icon)}<span>${name}</span><span>${all.filter(k=>id==='all'||k.team===id).length}</span></button>`).join('')}<div class="hm-note" style="padding:10px">${I('badge-check')}Every guide has an owner and a next review date.</div></aside><div><p class="hd-results-count">${items.length} ${items.length===1?'resource':'resources'}${knowledgeSaved?' · Saved by you':''}</p>${knowledgeRows(items)}</div></div>${companyFooter()}`;}
function articlePage(){
 const id=activePageId.slice(6),d=activeDoc(),seed=knowledgeSeeds.find(k=>k.id===id),record=pageRecord(activePageId);
 const k=preview?{id,title:d.title,summary:d.summary||d.tagline,team:d.department||'people',owner:d.owner||'ella',kind:d.docType||'Guide',record,checklist:d.docType==='Checklist'?(d.checklistText??seed?.checklist?.join('\n')??'').split('\n').map(x=>x.trim()).filter(Boolean).slice(0,12):null}:guideInfo(id);
 if(!k)return depthBase.dedicatedPage();
 const owner=personBy(k.owner)||personBy('ella'),blocks=d.sections.flatMap(s=>s.blocks.filter(b=>!b.hidden)),saved=state.bookmarks.includes('page:'+activePageId);
 const checklist=k.checklist?.length?`<div aria-label="Personal checklist">${k.checklist.map((label,n)=>`<label class="hd-checkitem"><input type="checkbox" data-guide-check="${id}:${n}" ${!preview&&(state.guideChecks[id]||[]).includes(n)?'checked':''} ${preview?'disabled':''}><span>${esc(label)}</span></label>`).join('')}</div><p class="hc-small hc-muted">${preview?'Staff can tick these steps in their personal reading view.':`${(state.guideChecks[id]||[]).filter(n=>n<k.checklist.length).length} of ${k.checklist.length} complete · Your preview progress`}</p>`:'';
 return `${preview?`<div class="hc-previewbar"><span class="hc-row">${I('eye')}Draft preview · Visible to editors only</span>${B('Back to designer','preview-back','pencil')}</div>`:`<div class="hd-breadcrumb">${TB('Knowledge library','hd-route','resources','arrow-left')}<span> / ${teamName(k.team)}</span></div>`}<div class="hd-doc-title"><div class="hc-row hc-between"><span class="hc-tag">${k.kind} · ${preview?'Unpublished draft':'Version '+k.record.revision}</span>${!preview?`<div class="hc-row">${B(saved?'Saved':'Save guide','hd-save-guide',saved?'bookmark-check':'bookmark','',id)}${state.role==='editor'?B(k.record.draft?'Continue draft':'Edit guide','edit-content-page','pencil','',activePageId):''}</div>`:''}</div><p style="margin-top:14px">${esc(k.summary)}</p><div class="hd-ownerbar" style="margin-bottom:0"><span>Updated ${esc(d.date)} · Owned by ${teamName(k.team)}</span><span>Next review ${esc(d.reviewDate||'12 Jan 2027')}</span></div></div><div class="hd-document"><article class="hd-article-body">${d.sections.map(s=>`<section class="hc-section hd-guide-section" data-tone="${s.tone}" aria-label="${esc(s.name)}"><div class="hd-guide-grid">${s.blocks.filter(b=>!b.hidden).map(b=>`<section class="hd-article-section" data-tone="${b.tone}" id="hd-section-${blocks.indexOf(b)}" style="grid-column:span ${b.width};min-height:${b.height||0}px"><h3>${esc(b.title)}</h3>${b.type==='text'?b.text.split('\n\n').map(p=>`<p>${esc(p)}</p>`).join(''):blockContent(b)}${blocks.indexOf(b)===Math.min(1,blocks.length-1)?checklist:''}</section>`).join('')}</div></section>`).join('')}${!blocks.length?checklist:''}${!preview?`<div class="hd-feedback"><span>Was this useful?</span><button class="hc-btn" data-action="hd-helpful" data-value="${id}" aria-pressed="${state.helpfulGuides.includes(id)}">${I('thumbs-up')}${state.helpfulGuides.includes(id)?'Thanks for your feedback':'Yes, helpful'}</button>${TB('Report an issue','hd-report',id,'flag')}</div>`:''}</article><aside class="hd-article-side"><section><h3>On this page</h3><div class="hc-toc">${blocks.map((b,i)=>`<button data-action="hd-guide-jump" data-value="${i}">${esc(b.title)}</button>`).join('')}</div></section><section><h3>Content owner</h3>${compactPerson(owner)}<p style="margin-top:9px">The owner keeps this guide clear and up to date.</p></section>${!preview?`<section><h3>Related resources</h3>${guideList().filter(x=>x.id!==id&&x.team===k.team).slice(0,3).map(x=>`<button class="hd-resource-mini" data-action="hd-article" data-value="${x.id}">${I('file-text')}<span><b>${esc(x.title)}</b><small>${x.kind}</small></span></button>`).join('')}</section><section>${B('Ask the team','hd-service','message-circle','',k.team==='it'?'it':k.team==='people'?'hr':k.team==='learning'?'learning':'maintenance')}</section>`:''}</aside></div><footer class="hc-pagefoot"><span>${preview?'Draft · Editors only':'Sample company guidance · Fictional preview'}</span>${preview?TB('Back to designer','preview-back','','arrow-left'):TB('Visit '+teamName(k.team),'hd-space',k.team,'arrow-up-right')}</footer>`;
}


blockContent=function(b){if(b.type==='departments')return spaceCards(true,b.count||4);if(b.type==='services')return serviceTiles(serviceSubset(b.department).slice(0,b.count||4),true);if(b.type==='directory'){if(b.department&&b.department!=='all')return `<div class="hd-profile-links">${colleagues.filter(p=>p.department===b.department).slice(0,b.count||3).map(p=>compactPerson(p)).join('')}</div>`;return `<div class="hd-finder"><div class="hd-faces">${['ella','noah','daniel','sam'].map(id=>avatar(personBy(id).name)).join('')}</div><p>A name, a role or someone who can help. Find colleagues across every team.</p>${depthSearch('people-widget','Find a colleague','','Name, role or expertise')}${TB('Explore the directory','hd-route','directory','arrow-right')}</div>`;}if(b.type==='knowledge')return guideList().filter(k=>!b.department||b.department==='all'||k.team===b.department).slice(0,b.count||3).map(k=>`<button class="hd-resource-mini" data-action="hd-article" data-value="${k.id}">${I(k.kind==='Checklist'?'list-checks':'file-text')}<span><b>${esc(k.title)}</b><small>${k.kind} · ${teamName(k.team)}</small></span></button>`).join('')||'<p class="hc-small hc-muted">Published guides will appear here.</p>';if(b.type==='news'&&b.department&&b.department!=='all'){const items=allStoryItems().filter(s=>pageRecord(s.id)?.published?.department===b.department&&pageRecord(s.id).published.showInNews!==false).slice(0,b.count||2);return items.length?newsMarkup(items,b.layout):'<p class="hc-small hc-muted">Publish a team update to show it here.</p>';}return depthBase.blockContent(b);};
blockMarkup=function(b,editing=false){let html=depthBase.blockMarkup(b,editing);if(!editing&&['departments','services','directory','knowledge'].includes(b.type))html=html.replace(`</h2></div>`,`</h2>${TB('See all','hd-block-more',b.type+':'+(b.department||'all'))}</div>`);if(!editing&&b.type==='news'&&b.department&&b.department!=='all')html=html.replace(TB('See all','nav','news'),TB('See all','hd-block-more','news:'+b.department));return html;};

properties=function(){
 const d=edit;
 if(activePageId&&inspectorMode==='settings'&&(!selected||selected.kind==='page')&&['knowledge','department'].includes(d.kind)){
  const pf=(...args)=>field(...args).replaceAll('data-prop=','data-page-prop='),resource=d.kind==='knowledge';
  return inspectorShell(resource?'Resource settings':'Department settings',`<span class="hc-tag">${resource?'Knowledge resource':'Department space'} · Shared with all staff</span>${pf(resource?'Resource title':'Space title','title',d.title)}${pf('Summary','summary',d.summary||d.tagline,'textarea')}${resource?pf('Owning team','department',d.department||'people','select',companyTeams.map(t=>[t.id,t.name]))+pf('Resource type','docType',d.docType||'Guide','select',['Guide','Process','Checklist'])+pf('Content owner','owner',d.owner||'ella','select',colleagues.map(p=>[p.id,p.name]))+pf('Next review date','reviewDate',d.reviewDate||'12 Jan 2027')+(d.docType==='Checklist'?pf('Checklist · one step per line','checklistText',d.checklistText||knowledgeSeeds.find(k=>'guide-'+k.id===activePageId)?.checklist?.join('\n')||'','textarea'):''):`<div class="hc-propgroup"><h3>Connected department</h3><p class="hc-small">${teamName(d.department)}</p><p class="hc-small hc-muted">This space brings together this team’s people, updates and resources.</p></div>`}<div class="hc-propgroup"><h3>Page design</h3>${B('Edit hero banner','edit-hero','image')}${B('Add content block','library','plus')}${B('Add section','add-section','layout-panel-top')}</div><p class="hc-small hc-muted">Changes stay in the shared draft until they are published.</p>`);
 }
 let html=depthBase.properties();const b=selected?.kind==='block'?blockFind(selected.id)?.b:null;
 if(b&&['services','directory','knowledge','news'].includes(b.type))html=html.replace('<div class="hc-propbody">','<div class="hc-propbody">'+field('Team content','department',b.department||'all','select',[['all','All teams'],...companyTeams.map(t=>[t.id,t.name])]));
 if(b&&['departments','services','directory','knowledge'].includes(b.type))html=html.replace('<div class="hc-propbody">','<div class="hc-propbody">'+field('Items to show','count',b.count||3,'select',[1,2,3,4]));
 if(activePageId&&inspectorMode==='settings'&&(!selected||selected.kind==='page'))html=html.replace('<div class="hc-propbody">','<div class="hc-propbody">'+field('Department','department',d.department||'','select',[['','Company-wide'],...companyTeams.map(t=>[t.id,t.name])]).replaceAll('data-prop=','data-page-prop='));
 return html;
};

editor=function(){let html=depthBase.editor();if(activeDoc().kind==='department')html=html.replace('Information page ·','Department space ·').replace('Design this page','Design this department space');if(activeDoc().kind==='knowledge')html=html.replace('Information page ·','Knowledge resource ·').replace('Design this page','Design this guide');return html;};
dedicatedPage=function(){const d=activeDoc();if(d.kind==='department')return departmentPage();if(d.kind==='knowledge')return articlePage();let html=depthBase.dedicatedPage();if(d.department&&!preview)html=`<div class="hd-breadcrumb">${TB(teamName(d.department),'hd-space',d.department,'arrow-left')}<span> / Team update</span></div>`+html;return html;};
header=function(){let html=depthBase.header();html=html.replace(/(class="hc-meter" data-action="nav" data-value="resources"[^>]*><b>)\d+/,(_,prefix)=>prefix+guideList().length);if(!activePageId&&!edit&&['teams','directory','services','resources'].includes(state.tab))html=html.replace(/<div class="hc-meters">[\s\S]*?<\/div>/,'').replace(/<div class="hc-hero-subactions">[\s\S]*?<\/div>/,'');return html;};
function crossSearch(savedOnly=false){const q=query.toLowerCase(),matches=text=>!q||text.toLowerCase().includes(q),ss=allStoryItems().filter(s=>matches(s.title+' '+s.summary)&&(!savedOnly||state.bookmarks.includes('story:'+s.id))),guides=guideList().filter(k=>matches(k.title+' '+k.summary+' '+k.topics.join(' '))&&(!savedOnly||state.bookmarks.includes('page:guide-'+k.id)||state.bookmarks.includes('resource:'+k.id))),persons=savedOnly?[]:colleagues.filter(p=>matches(p.name+' '+p.role+' '+p.skills.join(' '))),teams=companyTeams.filter(t=>spaceRecord(t.id)?.published&&matches(t.name+' '+t.summary)&&(!savedOnly||state.bookmarks.includes('page:space-'+t.id))),pages=pageList().filter(p=>p.published&&!['knowledge','department','story'].includes(p.published.kind)&&matches(p.published.title+' '+p.published.tagline)&&(!savedOnly||state.bookmarks.includes('page:'+p.id))),ev=events.filter(e=>matches(e.title+' '+e.description)&&(!savedOnly||state.bookmarks.includes('event:'+e.id))),total=ss.length+guides.length+persons.length+teams.length+pages.length+ev.length;const show=type=>globalType==='all'||globalType===type;return heading(savedOnly?'Your collection':'Across the company hub',savedOnly?'Saved for later':'Search results',query?`${total} results for “${esc(query)}”`:'Your saved stories, guides, pages and events.',query?TB('Clear search','clear-search','','x'):'')+`<div class="hm-albums" aria-label="Search result types">${[['all','All',total],['news','Stories',ss.length],['knowledge','Knowledge',guides.length],['people','People',persons.length],['pages','Pages & teams',pages.length+teams.length],['events','Events',ev.length]].filter(([id,name,count])=>count||id==='all').map(([id,name,count])=>`<button data-action="hd-search-type" data-value="${id}" aria-pressed="${globalType===id}">${name} ${count}</button>`).join('')}</div><div class="hc-stack">${show('news')&&ss.length?`<section><h3 class="hc-collection-label">Stories</h3>${newsMarkup(ss)}</section>`:''}${show('knowledge')&&guides.length?`<section><h3 class="hc-collection-label">Knowledge</h3>${knowledgeRows(guides)}</section>`:''}${show('people')&&persons.length?`<section><h3 class="hc-collection-label">People</h3>${peopleCards(persons)}</section>`:''}${show('pages')&&(pages.length||teams.length)?`<section><h3 class="hc-collection-label">Pages & teams</h3>${informationPageList([...teams.map(t=>({id:'space-'+t.id,published:spaceRecord(t.id).published})),...pages])}</section>`:''}${show('events')&&ev.length?`<section><h3 class="hc-collection-label">Events</h3>${eventList(ev)}</section>`:''}${!total?depthEmpty(savedOnly?'Nothing saved yet':'No matches yet',savedOnly?'Save a guide, story or event to keep it here.':'Try a name, a team or a shorter phrase.'):''}</div>`;}
collectionView=crossSearch;
reading=function(){if(activePageId)return depthBase.reading();if(query)return crossSearch(false);if(state.tab==='saved')return crossSearch(true);const content=state.tab==='teams'?teamsPage():state.tab==='directory'?peoplePage():state.tab==='services'?servicePage():state.tab==='resources'?knowledgePage():null;if(content!==null)return `${state.role==='editor'?`<div class="hm-launch">${B('Manage hub','hm-open','settings-2','ghost')}</div>`:''}`+content;let html=depthBase.reading();if(state.tab==='home'&&!preview)html=html.replace(/<footer class="hc-pagefoot">[\s\S]*?<\/footer>$/,companyFooter());return html;};
render=function(){depthBase.render();if(!activePageId&&['teams','directory','services','resources'].includes(state.tab)){const crumb=root.querySelector('.hc-crumb'),names={teams:'Teams',directory:'People',services:'Get help',resources:'Knowledge'};if(crumb)crumb.innerHTML=`${TB('Company Hub','hd-route','home','')} ${I('chevron-right')} ${names[state.tab]}${personId?' '+I('chevron-right')+' '+personBy(personId).name:''}`;}if(activePageId&&activeDoc().kind==='department'){const crumb=root.querySelector('.hc-crumb');if(crumb)crumb.innerHTML=`${TB('Company Hub','hd-route','home','')} ${I('chevron-right')} ${TB('Teams','hd-route','teams','')} ${I('chevron-right')} ${esc(activeDoc().title)}`;}if(activePageId&&activeDoc().kind==='knowledge'){const crumb=root.querySelector('.hc-crumb');if(crumb)crumb.innerHTML=`${TB('Company Hub','hd-route','home','')} ${I('chevron-right')} ${TB('Knowledge','hd-route','resources','')} ${I('chevron-right')} <span>${esc(activeDoc().title)}</span>`;}icons();};
function runDepthSearch(id){const input=root.querySelector(`[data-depth-search="${id}"] input`),value=input?.value.trim()||'';if(id==='people'||id==='people-widget'){peopleSearch=value;peopleView='cards';personId=null;activePageId=null;state.tab='directory';}if(id==='services'){serviceSearch=value;serviceView='services';requestId=null;}if(id==='knowledge')knowledgeSearch=value;query='';render();returnToTop();}
root.addEventListener('input',e=>{if(edit?.kind==='knowledge'&&e.target.dataset.pageProp==='summary'){edit.tagline=e.target.value;refreshLiveHero();}});
root.addEventListener('submit',e=>{if(e.target.dataset.depthSearch){e.preventDefault();if(!edit)runDepthSearch(e.target.dataset.depthSearch);}});
root.addEventListener('change',e=>{const key=e.target.dataset.depthFilter;if(key==='people-department')peopleDepartment=e.target.value;if(key==='people-site')peopleSite=e.target.value;if(key==='knowledge-kind')knowledgeKind=e.target.value;if(key){render();return;}if(e.target.dataset.guideCheck){const [id,num]=e.target.dataset.guideCheck.split(':'),n=Number(num),c=clone(state),checks=c.guideChecks[id]||[];c.guideChecks[id]=e.target.checked?[...new Set([...checks,n])]:checks.filter(x=>x!==n);if(depthCommit(c))render();}if(e.target.dataset.pageProp==='docType'&&edit){edit.category=edit.docType;refreshLiveHero();refreshProps();}if(e.target.dataset.pageProp==='owner'&&edit)edit.author=personBy(edit.owner)?.name||edit.author;});
function newGuideDialog(){openDialog('Create a knowledge resource','Give your teams a useful answer with a clear owner.',`<label class="hc-field">Title<input id="hd-guide-title" aria-label="Resource title" maxlength="90" placeholder="What will this help someone do?"></label><label class="hc-field">Resource type<select id="hd-guide-type" aria-label="New resource type"><option>Guide</option><option>Process</option><option>Checklist</option></select></label><label class="hc-field">Owning team<select id="hd-guide-team" aria-label="Owning team">${companyTeams.map(t=>`<option value="${t.id}">${t.name}</option>`).join('')}</select></label><p class="hm-error" id="hd-guide-error" role="alert"></p>`,B('Cancel','close')+B('Create draft','hd-guide-create','plus','primary'));}
function beginDepthDraft(id,d){activePageId=id;edit=d;preview=false;selected={kind:'page'};inspectorMode='settings';history=[clone(d)];future=[];newPagePending=true;query='';state.tab='pages';personId=null;requestId=null;close();render();returnToTop();}
handleAction=function(a,v,el){
 const navigating=['hd-route','hd-space','hd-person','hd-article','hd-service','hd-search','hd-my-requests','hd-org','hd-block-more'];
 if(edit&&navigating.includes(a)){if(preview)toast('Use Back to designer before exploring another page.');return;}
 if(['hd-new-update','hd-new-guide','hd-guide-create'].includes(a)&&state.role!=='editor')return;
 if(a==='hd-block-more'){const [type,team]=v.split(':');if(activePageId&&activeDoc().kind==='department'&&['news','knowledge','directory'].includes(type)){spaceTab={news:'news',knowledge:'knowledge',directory:'people'}[type];render();returnToTop();return;}if(type==='services'){serviceDepartment=team;serviceSearch='';serviceView='services';}if(type==='directory'){peopleDepartment=team;peopleSite='all';peopleSearch='';peopleView='cards';}if(type==='knowledge'){knowledgeTopic=team;knowledgeSearch='';knowledgeKind='all';knowledgeSaved=false;}routeDepth({departments:'teams',services:'services',directory:'directory',knowledge:'resources',news:'news'}[type]);return;}
 if(a==='hd-route'){routeDepth(v);return;}
 if(a==='hd-space'){if(!spaceRecord(v)?.published){toast('This department space is not published.');return;}spaceTab='overview';personId=null;requestId=null;openPage('space-'+v);return;}
 if(a==='hd-space-tab'){spaceTab=v;render();return;}
 if(a==='hd-follow-team'){const c=clone(state);c.followedTeams=c.followedTeams.includes(v)?c.followedTeams.filter(x=>x!==v):[...c.followedTeams,v];if(depthCommit(c,c.followedTeams.includes(v)?'Team followed. Find it quickly from Teams.':'Team unfollowed.'))render();return;}
 if(a==='hd-new-update'){const t=teamBy(v);if(!t||edit)return;const fresh=makeContentPage('An update from '+t.name,'story');Object.assign(fresh.d,{department:t.id,author:personBy(t.lead).name,hero:{...heroFor(fresh.d),image:t.image}});beginDepthDraft(fresh.id,fresh.d);return;}
 if(a==='hd-person'){goPerson(v);return;}
 if(a==='hd-people-back'){personId=null;render();returnToTop();return;}
 if(a==='hd-people-view'){peopleView=v;personId=null;render();return;}
 if(a==='hd-org'){peopleView='org';routeDepth('directory');return;}
 if(a==='hd-people-clear'){peopleSearch='';peopleDepartment='all';peopleSite='all';render();return;}
 if(a==='hd-contact'){const p=personBy(v);openDialog('Contact '+p.name,p.role,`<div class="hc-person">${avatar(p.name)}<div><b>${p.name}</b><small>${teamName(p.department)} · ${p.site}</small></div></div><div class="hc-detailfacts"><span><small>Work email · example</small>${personEmail(p)}</span><span><small>Team</small>${teamName(p.department)}</span></div><p class="hc-small hc-muted">These are fictional work contacts for the demonstration.</p>`,B('Close','close')+(teamBy(p.department)?B('Visit team space','hd-space','arrow-right','primary',p.department):B('View organisation','hd-org','network')));return;}
 if(a==='hd-staff-record'){const p=personBy(v);openDialog('Staff record preview',p.name,`<p class="hc-small hc-muted">In the application, authorised staff would open this person’s existing staff record. Directory details are maintained there.</p>`,B('Back to profile','close'));return;}
 if(a==='hd-search'){runDepthSearch(v);return;}
 if(a==='hd-service'){showService(v);return;}
 if(a==='hd-service-view'){serviceView=v;requestId=null;render();return;}
 if(a==='hd-service-filter'){serviceDepartment=v;render();return;}
 if(a==='hd-services-clear'){serviceSearch='';serviceDepartment='all';render();return;}
 if(a==='hd-my-requests'){serviceView='requests';requestId=null;routeDepth('services');return;}
 if(a==='hd-request'){requestId=v;state.tab='services';render();returnToTop();return;}
 if(a==='hd-handoff'){const s=staffServices.find(s=>s.id===v);openDialog(esc(s.destination),'Application destination preview',`<div class="hd-dialog-highlight"><strong>${s.title}</strong><p>This is where the existing ${s.team==='learning'?'learning':'HR'} area would open, using the staff member’s permissions and normal workflow.</p></div><div class="hc-detailfacts"><span><small>Opened from</small>Company Hub · Get help</span><span><small>Destination</small>${esc(s.destination)}</span></div>`,B('Back to service centre','hd-route','arrow-left','primary','services'));return;}
 if(a==='hd-request-review'){reviewRequest();return;}
 if(a==='hd-request-back'){showRequestForm();return;}
 if(a==='hd-request-submit'){if(!requestDraft?.title)return;const c=clone(state),id='DEMO-'+Date.now().toString(36).slice(-5).toUpperCase(),r={id,...requestDraft,status:'Received',date:'12 Oct 2026',owner:null};c.serviceRequests.unshift(r);c.serviceRequests=c.serviceRequests.slice(0,4);if(!depthCommit(c))return;close();requestDraft=null;activePageId=null;query='';state.tab='services';requestId=id;render();returnToTop();toast('Sample request created. Nothing was sent to a live team.');return;}
 if(a==='hd-article'){goGuide(v);return;}
 if(a==='hd-knowledge-topic'){knowledgeTopic=v;render();return;}
 if(a==='hd-knowledge-saved'){knowledgeSaved=!knowledgeSaved;render();return;}
 if(a==='hd-knowledge-clear'){knowledgeSearch='';knowledgeTopic='all';knowledgeKind='all';knowledgeSaved=false;render();return;}
 if(a==='hd-save-guide'){const id='page:guide-'+v,c=clone(state);c.bookmarks=c.bookmarks.includes(id)?c.bookmarks.filter(x=>x!==id):[...c.bookmarks,id];if(depthCommit(c,c.bookmarks.includes(id)?'Guide saved for later.':'Guide removed from your saved collection.'))render();return;}
 if(a==='hd-helpful'){const c=clone(state);c.helpfulGuides=c.helpfulGuides.includes(v)?c.helpfulGuides.filter(x=>x!==v):[...c.helpfulGuides,v];if(depthCommit(c))render();return;}
 if(a==='hd-guide-jump'){root.querySelector('#hd-section-'+v)?.scrollIntoView({block:'start'});return;}
 if(a==='hd-report'){const k=guideInfo(v);openDialog('Help keep this guide useful',esc(k.title),`<label class="hc-field">What needs attention?<select id="hd-issue-type" aria-label="Content issue"><option>Information is out of date</option><option>Something is unclear</option><option>A link is not working</option></select></label><label class="hc-field">A short note<textarea id="hd-issue-note" aria-label="Content issue note" maxlength="200" rows="3" placeholder="Use a sample note for this preview."></textarea></label><p class="hm-error" id="hd-issue-error" role="alert"></p><p class="hc-small hc-muted">The sample report is stored in this preview. No message is sent.</p>`,B('Cancel','close')+B('Record sample feedback','hd-report-submit','flag','primary',v));return;}
 if(a==='hd-report-submit'){const note=root.querySelector('#hd-issue-note').value.trim();if(!note){root.querySelector('#hd-issue-error').textContent='Add a short note so the owner knows what to review.';return;}const c=clone(state);c.contentFlags.unshift({guide:v,issue:root.querySelector('#hd-issue-type').value,note});c.contentFlags=c.contentFlags.slice(0,4);if(!depthCommit(c))return;close();toast('Sample feedback recorded for the content owner. No message was sent.');return;}
 if(a==='hd-new-guide'){if(!edit)newGuideDialog();return;}
 if(a==='hd-guide-create'){const title=root.querySelector('#hd-guide-title').value.trim(),kind=root.querySelector('#hd-guide-type').value,team=root.querySelector('#hd-guide-team').value;if(title.length<4){root.querySelector('#hd-guide-error').textContent='Give the resource a clear title of at least four characters.';return;}const id='guide-'+Date.now().toString(36),t=teamBy(team),d={kind:'knowledge',department:team,owner:t.lead,docType:kind,title,tagline:'Add a short description of what this resource helps someone do.',summary:'',category:kind,author:personBy(t.lead).name,date:'12 Oct 2026',reviewDate:'12 Jan 2027',checklistText:kind==='Checklist'?'Add your first step\nAdd your next step':'',hero:{visual:'brand',height:'compact',icon:'book-open',showSearch:false,showMetrics:false},sections:[{id:id+'-content',name:'Resource content',tone:'plain',blocks:[pageText(id+'-overview','What you need to know','Explain who this resource is for and when it is useful.'),pageText(id+'-steps','Getting started','Describe the steps clearly and point to the right next action.')]}]};beginDepthDraft(id,d);return;}
 if(a==='hd-search-type'){globalType=v;render();return;}
 if(a==='clear-search'){globalType='all';}
 if(a==='search'||a==='global-search'){globalType='all';personId=null;requestId=null;}
 if(a==='nav'||a==='hm-follow'||a==='hm-home'||a==='hm-open'||a==='role'){personId=null;requestId=null;spaceTab='overview';globalType='all';}
 if(a==='resource'&&guideInfo(v)){goGuide(v);return;}
 if(a==='person'){const name=people[Number(v)]?.name,p=colleagues.find(p=>p.name===name);if(p){goPerson(p.id);return;}}
 if(a==='destination'&&!v?.startsWith('page:')&&!edit){if(/people directory|colleague/i.test(v)){routeDepth('directory');return;}if(/resource|polic|guide/i.test(v)){routeDepth('resources');return;}if(/learning/i.test(v)){openPage('space-learning');return;}if(v==='IT & Support'){routeDepth('services');return;}}
 depthBase.handleAction(a,v,el);
};
